$('#saveRate').onclick=()=>{const t=activeTrip();document.querySelectorAll('[data-rate]').forEach(i=>t.rates[i.dataset.rate]=Number(i.value||0));t.expenses.forEach(e=>{const oldRate=e.fxRate||1,newRate=e.currency==='TWD'?1:Number(t.rates[e.currency]||1);if(!e.shareAmounts)e.shareAmounts=Object.fromEntries(Object.entries(e.shares||{}).map(([id,v])=>[id,Number(v)/oldRate]));e.fxRate=newRate;e.twdAmount=Number(e.amount)*newRate;e.shares=Object.fromEntries(Object.entries(e.shareAmounts||{}).map(([id,v])=>[id,Number(v)*newRate]))});save();render();toast('匯率已更新，所有外幣支出將依新匯率計算')};
function calculateWithSettlements(t){const z=baseCalculate(t);(t.settlements||[]).forEach(s=>{const a=Number(s.amount);if(z.balances[s.from]!==undefined)z.balances[s.from]+=a;if(z.balances[s.to]!==undefined)z.balances[s.to]-=a});const cs=Object.entries(z.balances).filter(([,v])=>v>.01).map(([id,amount])=>({id,amount})),ds=Object.entries(z.balances).filter(([,v])=>v<-.01).map(([id,amount])=>({id,amount:-amount}));z.transfers=[];let d=0,c=0;while(d<ds.length&&c<cs.length){const a=Math.min(ds[d].amount,cs[c].amount);z.transfers.push({from:nameOf(t,ds[d].id),to:nameOf(t,cs[c].id),amount:a});ds[d].amount-=a;cs[c].amount-=a;if(ds[d].amount<.01)d++;if(cs[c].amount<.01)c++}return z}
