function handleDateTripSubmit(e){if(!['tripDateCreate','tripDateEdit'].includes(modalMode))return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(e.target),start=fd.get('startDate'),end=fd.get('endDate'),flag=fd.get('tripFlag')||'',currencies=[...new Set(['TWD',...fd.getAll('currencies')])];if(new Date(`${end}T00:00:00`)<new Date(`${start}T00:00:00`)){toast('結束日期不能早於開始日期');return}if(modalMode==='tripDateCreate'){const rates=Object.fromEntries(currencies.map(c=>[c,1]));const tr={id:`trip-${Date.now()}`,name:fd.get('name'),flag,startDate:start,endDate:end,dates:dateLabel(start,end),currencies,rates,calendarMonth:start.slice(0,7),selectedDay:start,members:[{id:data.ownerId,name:'你'}],expenses:[]};data.trips.push(tr);data.activeTripId=tr.id;toast('旅行已建立')}else{const t=activeTrip();t.name=fd.get('name');t.flag=flag;t.startDate=start;t.endDate=end;t.dates=dateLabel(start,end);t.calendarMonth=start.slice(0,7);t.selectedDay=start;const used=[...new Set(t.expenses.map(x=>x.currency))];t.currencies=[...new Set([...currencies,...used])];t.rates=t.rates||{};t.currencies.forEach(c=>{if(t.rates[c]===undefined)t.rates[c]=1});toast('旅行設定已更新')}save();closeModal();render()}
