function enhanceStatsPie(){const t=activeTrip();if(!t||!$('#statsPanel'))return;const totals={};t.expenses.forEach(e=>totals[e.category||'其他']=(totals[e.category||'其他']||0)+Number(e.twdAmount));const entries=Object.entries(totals),grand=entries.reduce((a,[,v])=>a+v,0),colors=['#7567c8','#ee806b','#4a9cc5','#eda65a','#e59abb','#62a883','#b39b68'];let cursor=0;const stops=entries.map(([k,v],i)=>{const start=cursor;cursor+=v/grand*100;return `${colors[i%colors.length]} ${start}% ${cursor}%`}).join(',');$('#statsPanel').innerHTML=`<div class="stats-heading"><div><p class="section-kicker">TRIP INSIGHTS</p><h2>花費概覽</h2></div><span class="count-pill">圓餅圖 · 台幣</span></div><div class="pie-layout"><div class="pie-chart" style="background:conic-gradient(${stops||'#dedbd1 0 100%'})"><div class="pie-hole"><strong>${money(grand,'TWD')}</strong><span>總支出</span></div></div><div class="pie-legend">${entries.map(([k,v],i)=>`<div><span><i style="background:${colors[i%colors.length]}"></i>${categoryIcons[k]||'✦'} ${esc(k)}</span><strong>${grand?Math.round(v/grand*100):0}%</strong></div>`).join('')||'<span class="muted-text">新增支出後會顯示占比。</span>'}</div></div>`}
const pieRender=render;render=()=>{pieRender();enhanceStatsPie()};
render();
function makeMemberFields(){const t=activeTrip();if(!t)return;document.querySelectorAll('.member-row').forEach((row,i)=>{const m=t.members[i],info=row.querySelector('.member-info'),avatar=info?.querySelector('.avatar'),name=info?.querySelector('span:not(.avatar)');if(!m||!info)return;if(avatar){avatar.textContent='👤';avatar.className=`avatar person avatar-color-${i%5}`}if(name){const input=document.createElement('input');input.className='member-name-input';input.value=m.name;input.setAttribute('aria-label','成員名稱');name.replaceWith(input)}let actions=row.querySelector('.member-actions');if(!actions){actions=document.createElement('span');actions.className='member-actions';row.append(actions)}actions.innerHTML=`<button data-member-save="${m.id}" type="button">儲存</button>${m.id===data.ownerId?'':'<button data-member-delete="'+m.id+'" type="button">刪除</button>'}`;});document.querySelectorAll('[data-member-save]').forEach(b=>b.onclick=()=>{const row=b.closest('.member-row'),input=row.querySelector('.member-name-input'),m=t.members.find(x=>x.id===b.dataset.memberSave);if(input.value.trim()){m.name=input.value.trim();save();render();toast('成員資料已更新')}})}
const memberRender=render;render=()=>{memberRender();makeMemberFields()};
render();
function openTripEdit(){const t=activeTrip();if(!t)return;modalMode='tripEdit';$('#modalBackdrop').classList.remove('hidden');$('#modalKicker').textContent='TRIP SETTINGS';$('#modalTitle').textContent='修改旅行設定';$('#modalForm').innerHTML=`<div class="field"><label>旅行名稱</label><input name="name" value="${esc(t.name)}" required autofocus></div><div class="field"><label>日期範圍</label><input name="dates" value="${esc(t.dates)}"></div><div class="field"><label>使用幣別（可複選）</label><select name="currencies" multiple size="7">${currencyOptions.map(x=>`<option value="${x[0]}" ${t.currencies.includes(x[0])?'selected':''}>${x[0]} · ${x[1]}</option>`).join('')}</select><small class="field-hint">已有歷史支出的幣別會自動保留。</small></div><div class="form-actions"><button class="button button-primary">儲存旅行設定</button></div>`}
document.addEventListener('submit',e=>{if(modalMode!=='tripEdit')return;e.preventDefault();e.stopImmediatePropagation();const fd=new FormData(e.target),t=activeTrip(),selected=fd.getAll('currencies'),used=[...new Set(t.expenses.map(x=>x.currency))],currencies=[...new Set([...selected,...used])];if(!currencies.length){toast('至少選擇一種幣別');return}t.name=fd.get('name');t.flag=fd.get('tripFlag')||'';t.dates=fd.get('dates');t.currencies=currencies;t.rates=t.rates||{};currencies.forEach(c=>{if(t.rates[c]===undefined)t.rates[c]=1});save();closeModal();render();toast('旅行設定已更新')},true);
