categoryIcons={餐飲:'🍜',交通:'🚕',住宿:'🏨',娛樂:'🎟️',購物:'🛍️','刷卡手續費':'💳',其他:'✦'};
function enhanceProduct(){const t=activeTrip();if(!t)return;const rows=[...document.querySelectorAll('.expense-row')];rows.forEach((row,i)=>{const e=t.expenses[t.expenses.length-1-i];if(e){const icon=row.querySelector('.expense-icon');if(icon)icon.textContent=categoryIcons[e.category]||'✦';row.dataset.search=`${e.title} ${e.category} ${nameOf(t,e.payer)}`.toLowerCase();}});const search=($('#expenseSearch')?.value||'').toLowerCase(),cat=$('#expenseCategoryFilter')?.value||'';rows.forEach(r=>{r.hidden=!!((search&&!r.dataset.search.includes(search))||(cat&&!r.dataset.search.includes(cat)))});const totals={};t.expenses.forEach(e=>totals[e.category||'其他']=(totals[e.category||'其他']||0)+Number(e.twdAmount));const avg=t.expenses.length?Object.values(totals).reduce((a,v)=>a+v,0)/new Set(t.expenses.map(e=>e.date)).size:0;$('#statsPanel').innerHTML=`<div class="stats-heading"><div><p class="section-kicker">TRIP INSIGHTS</p><h2>花費概覽</h2></div><span class="count-pill">每日平均 ${money(avg,'TWD')}</span></div><div class="stats-bars">${Object.entries(totals).map(([k,v])=>`<div class="stat-bar"><div><span>${categoryIcons[k]||'✦'} ${esc(k)}</span><strong>${money(v,'TWD')}</strong></div><i><b style="width:${Math.max(6,Math.round(v/(Object.values(totals).reduce((a,x)=>a+x,0)||1)*100))}%"></b></i></div>`).join('')||'<span class="muted-text">新增支出後會顯示分類統計。</span>'}</div>`;const list=$('#midSettlementList');if(list)list.innerHTML=(t.settlements||[]).length?t.settlements.slice().reverse().map(s=>`<div class="mid-settlement-row"><span>${esc(nameOf(t,s.from))} → ${esc(nameOf(t,s.to))}</span><strong>${settlementMoney(s.amount)}</strong><small>${s.date}</small><div class="settlement-actions"><button data-settle-edit="${s.id}">編輯</button><button data-settle-delete="${s.id}">刪除</button></div></div>`).join(''):'<span class="muted-text">尚未記錄中途結算。</span>';document.querySelectorAll('[data-settle-delete]').forEach(b=>b.onclick=()=>{if(confirm('確定刪除這筆中途結算嗎？')){t.settlements=t.settlements.filter(s=>s.id!==b.dataset.settleDelete);save();render()}});document.querySelectorAll('[data-settle-edit]').forEach(b=>b.onclick=()=>{const s=t.settlements.find(x=>x.id===b.dataset.settleEdit),v=prompt('請輸入新的台幣結算金額',s.amount);if(v!==null&&Number(v)>=0){s.amount=Number(v);save();render()}});document.querySelectorAll('.member-row').forEach((row,i)=>{const m=t.members[i];if(!m||m.id===data.ownerId)return;const actions=document.createElement('span');actions.className='member-actions';actions.innerHTML=`<button data-member-edit="${m.id}">編輯</button><button data-member-delete="${m.id}">刪除</button>`;row.append(actions)});document.querySelectorAll('[data-member-edit]').forEach(b=>b.onclick=()=>{const m=t.members.find(x=>x.id===b.dataset.memberEdit),v=prompt('修改成員名稱',m.name);if(v?.trim()){m.name=v.trim();save();render()}});document.querySelectorAll('[data-member-delete]').forEach(b=>b.onclick=()=>{const id=b.dataset.memberDelete,used=t.expenses.some(e=>Object.keys(e.shares||{}).includes(id));if(used){toast('已有帳務紀錄的成員不能刪除');return}if(confirm('確定刪除這位成員嗎？')){t.members=t.members.filter(m=>m.id!==id);save();render()}})}
function fixCategoryIcons(){const t=activeTrip();if(!t)return;document.querySelectorAll('.day-expense').forEach((row,i)=>{const list=t.expenses.filter(e=>e.date===t.selectedDay),e=list[i];if(e&&row.firstElementChild)row.firstElementChild.textContent=`${categoryIcons[e.category]||'✦'} ${e.title} ${e.currency}`})}
