$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='travel-ledger-backup.json';a.click();URL.revokeObjectURL(a.href);toast('資料已匯出')};$('#importData').onclick=()=>$('#importFile').click();$('#importFile').onchange=e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{data=JSON.parse(reader.result);normalize();save();render();toast('資料已匯入')}catch{toast('匯入失敗，請確認檔案格式')}};reader.readAsText(file)};
$('#copyTrip').onclick=()=>{const t=activeTrip(),copy=structuredClone(t);copy.id=`trip-${Date.now()}`;copy.name=`${copy.name} 副本`;copy.settlements=[];data.trips.push(copy);data.activeTripId=copy.id;save();render();toast('旅行已複製')};
