// Stable trip settings UI: keep the flag selector and currency checkboxes in the form itself.
function stableCurrencyChecks(selected){const chosen=new Set(['TWD',...(selected||[])]);return `<div class="currency-checkboxes currency-checks-grid">${currencyOptions.map(([code,label])=>`<label class="currency-check ${code==='TWD'?'fixed-currency':''}"><input type="checkbox" name="currencies" value="${code}" ${chosen.has(code)?'checked':''} ${code==='TWD'?'disabled':''}>${code} · ${label}</label>`).join('')}</div><input type="hidden" name="currencies" value="TWD"><small class="field-hint">台幣固定列入且為預設付款幣別，可複選其他幣別。</small>`}
function stableFlagField(t,edit){return `<div class="field emoji-field"><label for="tripFlag">國家／地區旗幟 Emoji</label><select id="tripFlag" name="tripFlag"><option value="">不設定</option>${flagOptions.map(([flag,label])=>`<option value="${flag}" ${edit&&t.flag===flag?'selected':''}>${flag} ${label}</option>`).join('')}</select><small class="field-hint">選擇後會顯示在旅行名稱前面。</small></div>`}
function openDateTripModal(edit=false){const t=activeTrip()||{};modalMode=edit?'tripDateEdit':'tripDateCreate';editingId=null;$('#modalBackdrop').classList.remove('hidden');$('#modalKicker').textContent=edit?'TRIP SETTINGS':'NEW TRIP';$('#modalTitle').textContent=edit?'修改旅行設定':'新增旅行';const start=edit?(t.startDate||'2026-03-12'):'',end=edit?(t.endDate||'2026-03-17'):'';const selected=edit?(t.currencies||[]):['TRY','EUR','USD'];$('#modalForm').innerHTML=`<div class="field"><label>旅行名稱</label><input name="name" value="${edit?esc(t.name||''):''}" placeholder="例如：🇹🇷 土耳其之旅" required autofocus></div>${stableFlagField(t,edit)}<div class="form-row"><div class="field"><label>開始日期</label><input name="startDate" type="date" value="${start}" required></div><div class="field"><label>結束日期</label><input name="endDate" type="date" value="${end}" required></div></div><div class="field"><label>使用幣別（可複選）</label>${stableCurrencyChecks(selected)}</div><div class="form-actions"><button class="button button-primary">${edit?'儲存旅行設定':'建立旅行'}</button></div>`;$('#tripFlag').addEventListener('change',()=>{pendingFlag=$('#tripFlag').value})}
function openTripEdit(){const t=activeTrip();if(!t)return;modalMode='tripEdit';$('#modalBackdrop').classList.remove('hidden');$('#modalKicker').textContent='TRIP SETTINGS';$('#modalTitle').textContent='修改旅行設定';$('#modalForm').innerHTML=`<div class="field"><label>旅行名稱</label><input name="name" value="${esc(t.name||'')}" required autofocus></div>${stableFlagField(t,true)}<div class="field"><label>日期範圍</label><input name="dates" value="${esc(t.dates||'')}"></div><div class="field"><label>使用幣別（可複選）</label>${stableCurrencyChecks(t.currencies||[])}</div><div class="form-actions"><button class="button button-primary">儲存旅行設定</button></div>`;$('#tripFlag').addEventListener('change',()=>{pendingFlag=$('#tripFlag').value})}
document.addEventListener('change',e=>{if(e.target.id==='tripFlag')pendingFlag=e.target.value},true);
function displayTripFlags(){const trips=visibleTrips();document.querySelectorAll('.trip-item').forEach((b,i)=>{const t=trips[i],n=b.querySelector('.trip-name');if(t&&n)n.innerHTML=flagVisual(t.flag||t.emoji)+' '+esc(t.name)});const t=activeTrip(),title=$('#tripTitle');if(t&&title)title.innerHTML=flagVisual(t.flag||t.emoji)+' '+esc(t.name)}
const flagDisplayRender=render;render=()=>{flagDisplayRender();displayTripFlags()};
document.getElementById('deleteTrip')?.addEventListener('click',()=>{const t=activeTrip();if(!t)return;if(data.trips.length<=1){toast('至少保留一個旅行，無法刪除最後一個旅行');return}if(confirm('確定刪除「'+t.name+'」嗎？此旅行的支出與設定也會一併刪除。')){data.trips=data.trips.filter(x=>x.id!==t.id);data.activeTripId=data.trips[0]?.id||null;save();render();toast('旅行已刪除')}});
