function enhanceStatsPie(){const t=activeTrip(),panel=$('#statsPanel');if(!t||!panel)return;const totals={};t.expenses.forEach(e=>totals[e.category||'其他']=(totals[e.category||'其他']||0)+Number(e.twdAmount||0));const entries=Object.entries(totals),grand=entries.reduce((a,[,v])=>a+v,0),colors=['#7567c8','#ee806b','#4a9cc5','#eda65a','#e59abb','#62a883','#b39b68'];let cursor=0;const stops=entries.map(([k,v],i)=>{const start=cursor;cursor+=grand?v/grand*100:0;return colors[i%colors.length]+' '+start+'% '+cursor+'%'}).join(',');const legend=entries.map(([k,v],i)=>'<div><span><i style="background:'+colors[i%colors.length]+'"></i>'+ (categoryIcons[k]||'✦')+' '+esc(k)+'</span><strong>'+ (grand?Math.round(v/grand*100):0)+'%</strong></div>').join('')||'<span class="muted-text">新增支出後會顯示占比。</span>';const max=Math.max(...entries.map(([,v])=>v),1);const bars=entries.map(([k,v],i)=>'<div class="category-bar"><div><span>'+ (categoryIcons[k]||'✦')+' '+esc(k)+'</span><strong>'+money(v,'TWD')+'</strong></div><div class="category-bar-track"><b style="width:'+Math.max(5,Math.round(v/max*100))+'%;background:'+colors[i%colors.length]+'"></b></div></div>').join('')||'<span class="muted-text">新增支出後會顯示分類金額。</span>';panel.innerHTML='<div class="stats-heading"><div><p class="section-kicker">TRIP INSIGHTS</p><h2><span class="heading-icon" aria-hidden="true">📊</span>花費概覽</h2></div><span class="count-pill">圓餅圖＋長條圖 · 台幣</span></div><div class="stats-visuals"><div class="stats-pie-side"><div class="pie-chart" style="background:conic-gradient('+ (stops||'#dedbd1 0 100%') +')"><div class="pie-hole"><strong>'+money(grand,'TWD')+'</strong><span>總支出</span></div></div><div class="pie-legend">'+legend+'</div></div><div class="category-bars"><p class="chart-label">各類別支出金額</p>'+bars+'</div></div>'}
const finalChartRender=render;render=()=>{finalChartRender();enhanceStatsPie()};
render();
function settlementMoney(v){return money(Math.ceil(Number(v)||0),'TWD')}
function shiftCalendarMonth(delta){const t=activeTrip();if(!t)return;const [year,month]=t.calendarMonth.split('-').map(Number),date=new Date(year,month-1+delta,1);t.calendarMonth=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');save();renderCalendar(t)}
$('#calendarPrev').onclick=()=>shiftCalendarMonth(-1);$('#calendarNext').onclick=()=>shiftCalendarMonth(1);
function placeExpenseCategory(){if(modalMode!=='expense')return;const form=$('#modalForm'),titleField=[...form.querySelectorAll('.field')].find(x=>x.querySelector('input[name="title"]')),categoryField=[...form.querySelectorAll('.field')].find(x=>x.querySelector('select[name="category"]'));if(titleField&&categoryField&&titleField.nextElementSibling!==categoryField)titleField.after(categoryField)}
const expenseFormObserver=new MutationObserver(placeExpenseCategory);expenseFormObserver.observe($('#modalForm'),{childList:true,subtree:true});
placeExpenseCategory();
